node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createFeed } from './src/index.mjs';
const feed = createFeed();
const input = { nested: { values: [1] } };
const first = feed.publishBatch('a', [{ type: 'created', payload: input }]);
input.nested.values[0] = 8;
first[0].payload.nested.values[0] = 9;
assert.equal(feed.history('a')[0].payload.nested.values[0], 1);
const deliveries1 = [], deliveries2 = [];
feed.subscribe('a', 0, r => { deliveries1.push(r); r.payload.nested.values[0] = 10; });
feed.subscribe('a', 0, r => deliveries2.push(r));
assert.equal(deliveries2[0].payload.nested.values[0], 1);
assert.throws(() => feed.publishBatch('a', [
  { type: 'valid', payload: { ok: true } },
  { type: 'invalid', payload: { bad: () => {} } },
]));
assert.deepEqual(feed.history('a').map(r => r.sequence), [1]);
assert.equal(deliveries1.length, 1);
const second = feed.publishBatch('a', [{ type: 'next', payload: { ok: true } }]);
assert.equal(second[0].sequence, 2);
assert.equal(deliveries1[1].sequence, 2);
assert.equal(deliveries2[1].payload.ok, true);
feed.publishBatch('b', [{ type: 'other', payload: {} }]);
assert.deepEqual(feed.history('a', 1).map(r => r.sequence), [2]);
assert.equal(feed.publishBatch('a', []).length, 0);
console.log('contract checks passed');
